export type StatutAffaire = 'EN_COURS' | 'TERMINEE' | 'SUSPENDUE' | 'ANNULEE';

export const STATUT_AFFAIRE: Record<StatutAffaire, { label: string; color: string; bg: string }> = {
  EN_COURS:  { label: 'En cours',  color: '#1D4ED8', bg: '#EFF6FF' },
  TERMINEE:  { label: 'Terminée',  color: '#15803D', bg: '#F0FDF4' },
  SUSPENDUE: { label: 'Suspendue', color: '#B45309', bg: '#FFFBEB' },
  ANNULEE:   { label: 'Annulée',   color: '#6B7280', bg: '#F3F4F6' },
};

export interface HistoriqueEntry {
  action: string;
  date: string;
  utilisateurId: string;
  details: string;
}

export interface Affaire {
  id: string;
  reference: string;
  nom: string;
  description?: string;
  dateDebut: string;
  dateFin?: string;
  statut: StatutAffaire;
  creePar: string;
  dateCreation: string;
  dateDerniereModification: string;
  historique: HistoriqueEntry[];
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  number: number;
  size: number;
}
